<script setup lang="ts">
import { computed, onUnmounted, reactive, ref, shallowRef, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { feedback as ElMessage } from '../utils/feedback'
import { api, ApiError } from '../api/client'
import { can, contextGeneration, session, switchingTenant } from '../stores/session'
import { contextTransitionGuards } from '../utils/contextTransitionGuard'
import { createWorksheetWorkspace, emptyWorksheetState, type WorksheetState } from '../utils/inspectionWorksheetWorkspace'
import { readWorksheetSource, type WorksheetContext, type WorksheetDetail, type WorksheetSource, type WorksheetView } from '../utils/inspectionWorksheets'
import { readInspectionPage, validInspectionText, type InspectionPage } from '../utils/inspectionTemplates'
import { worksheetAssetChoice, worksheetAssetChoices, worksheetEditorRows, worksheetEditorObservations, type WorksheetAssetChoices, type WorksheetEditorRow } from '../utils/inspectionWorksheetForm'
import { displayTime } from '../utils/display'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
import InspectionWorksheetFacts from '../components/InspectionWorksheetFacts.vue'
import InspectionSourceRevisionReader from '../components/InspectionSourceRevisionReader.vue'
import type { InspectionSourceTarget } from '../utils/inspectionSourceRevision'
const inspectionSourceTarget=shallowRef<InspectionSourceTarget|null>(null)
const actions = { CREATE: '新建', UPDATE: '修订', ARCHIVE: '归档', RESTORE: '恢复' }
const assetFilter = ref(''), view = ref<WorksheetView>('CURRENT'), validation = ref(''), expandedVersion = ref<number | null>(null)
const mode = ref<'CREATE' | 'UPDATE' | 'RESTORE' | null>(null), baseline = shallowRef<WorksheetDetail | null>(null), creationSource = shallowRef<WorksheetSource | null>(null), initial = ref('')
const form = reactive({ rows: [] as WorksheetEditorRow[], timeKnown: false, timeText: '' })
const assetQuery = ref(''), templateQuery = ref(''), assetApplied = ref(''), templateApplied = ref(''), selectedAssetId = ref(''), selectedTemplateId = ref('')
const assets = shallowRef<WorksheetAssetChoices | null>(null), templates = shallowRef<InspectionPage | null>(null), sourcesBusy = ref(false), sourceError = shallowRef<unknown>(null)
let sourceEpoch = 0, sourceAbort: AbortController | null = null
const state = shallowRef<WorksheetState>(emptyWorksheetState()), workspace = createWorksheetWorkspace(api,value=>{state.value=value})
const permitted = computed(()=>Boolean(session.value?.mode==='remote_test' && session.value.user.role==='padmin' && can('inspection_worksheets:read') && !switchingTenant.value))
const writable = computed(()=>permitted.value && can('inspection_worksheets:write'))
const canChooseSource = computed(()=>writable.value && can('assets:read') && can('inspection_templates:read'))
const locked = computed(()=>!writable.value || Boolean(state.value.busy) || sourcesBusy.value || Boolean(state.value.attempt))
const sourcesLocked = computed(()=>!canChooseSource.value || Boolean(state.value.busy) || sourcesBusy.value || workspace.unresolved())
const contextKey = computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.user.role,permitted.value,writable.value,canChooseSource.value]))
function context(): WorksheetContext | null { const s=session.value;return s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,role:s.user.role,canRead:true,canWrite:writable.value}:null }
function payload(){return {expected_version:baseline.value?.version??0,...(mode.value==='CREATE'?{asset_id:creationSource.value?.asset.id,template_id:creationSource.value?.template.id,template_version:creationSource.value?.template.version}:{}),observations:worksheetEditorObservations(form.rows),reported_performed_at:form.timeKnown?form.timeText:null}}
const unsaved = computed(()=>mode.value!==null && state.value.attempt?.state!=='accepted' && (state.value.attempt?.state==='rejected' || JSON.stringify(payload())!==initial.value))
const nextList = computed(()=>state.value.page?.has_more && assetFilter.value===state.value.assetId && view.value===state.value.view && !state.value.busy)
const newerVersion = computed(()=>baseline.value && state.value.selected?.id===baseline.value.id && state.value.selected.version>baseline.value.version)
function clearEditor(){inspectionSourceTarget.value=null;mode.value=null;baseline.value=null;creationSource.value=null;initial.value='';validation.value='';expandedVersion.value=null;Object.assign(form,{rows:[],timeKnown:false,timeText:''})}
function clearSources(){sourceAbort?.abort();sourceAbort=null;++sourceEpoch;sourcesBusy.value=false;sourceError.value=null;assets.value=null;templates.value=null;assetQuery.value='';templateQuery.value='';assetApplied.value='';templateApplied.value='';selectedAssetId.value='';selectedTemplateId.value=''}
watch(contextKey,()=>{workspace.reset(context());clearEditor();clearSources();assetFilter.value='';view.value='CURRENT';if(permitted.value)void workspace.list()},{immediate:true,flush:'sync'})
async function sourceRead<T>(work:(signal:AbortSignal,scope:WorksheetContext)=>Promise<T>):Promise<T|null>{const scope=context();if(!scope||sourcesLocked.value)return null;const turn=++sourceEpoch,key=contextKey.value,controller=new AbortController();sourceAbort=controller;sourcesBusy.value=true;sourceError.value=null;try{const value=await work(controller.signal,{...scope});return turn===sourceEpoch&&key===contextKey.value&&!controller.signal.aborted?value:null}catch(error){if(turn===sourceEpoch&&key===contextKey.value)sourceError.value=error;return null}finally{if(turn===sourceEpoch&&key===contextKey.value){sourcesBusy.value=false;sourceAbort=null}}}
async function loadAssets(next=false){if(sourcesLocked.value)return false;const query=assetQuery.value,cursor=next&&assets.value?.has_more&&query===assetApplied.value?assets.value.next_cursor:null;if(next&&!cursor)return false;assets.value=null;selectedAssetId.value='';const value=await sourceRead(async(signal,scope)=>{if(typeof query!=='string'||query.length>100||!validInspectionText(query,100,false,false,false))throw new ApiError(0,'INVALID_ASSET_QUERY','资产查询最多100个UTF-16字符，不能含控制字符','—');const p=new URLSearchParams({page_size:'15',q:query});if(cursor)p.set('cursor',cursor);return worksheetAssetChoices(await api.request('/assets?'+p,{signal}),scope)});if(value){assets.value=value;assetApplied.value=query;return true}return false}
async function loadTemplates(next=false){if(sourcesLocked.value)return false;const query=templateQuery.value,before=next&&templates.value?.has_more&&query===templateApplied.value?{time:templates.value.next_before_created_at!,id:templates.value.next_before_id!}:undefined;if(next&&!before)return false;templates.value=null;selectedTemplateId.value='';const value=await sourceRead(async(signal,scope)=>{if(!validInspectionText(query,200,false,false,false))throw new ApiError(0,'INVALID_TEMPLATE_QUERY','模板查询文字无效','—');const p=new URLSearchParams({page_size:'15',view:'CURRENT',name_query:query});if(before){p.set('before_created_at',before.time);p.set('before_id',before.id)}return readInspectionPage(await api.request('/inspection-templates?'+p,{signal}),scope,'CURRENT','',before)});if(value){templates.value=value;templateApplied.value=query;return true}return false}
async function discard(){if(!unsaved.value)return true;try{await ElMessageBox.confirm('将替换尚未成功保存的执行单输入，不会自动合并或升级版本。是否继续？','保留未保存输入',{confirmButtonText:'确认替换',cancelButtonText:'保留输入',type:'warning'});return true}catch{return false}}
function canPrepare(){if(!writable.value||state.value.busy||sourcesBusy.value)return false;if(workspace.unresolved()){ElMessage.warning('原请求结果未知，请使用原请求重试，不能替换输入');return false}return true}
async function prepareCreate(){if(!canPrepare()||!canChooseSource.value)return false;const asset=assets.value?.items.find(row=>row.id===selectedAssetId.value),template=templates.value?.items.find(row=>row.id===selectedTemplateId.value);if(!asset||!template){validation.value='请先查询并明确选择当前租户资产和未归档模板';return false}const turn=contextKey.value;if(!await discard()||turn!==contextKey.value)return false;const selected=await sourceRead(async(signal,scope)=>{const [rawAsset,rawTemplate]=await Promise.all([api.request('/assets/'+asset.id,{signal}),api.request('/inspection-templates/'+template.id,{signal})]);const captured=await readWorksheetSource({asset:worksheetAssetChoice(rawAsset,scope,asset.id),template:rawTemplate},scope);if(captured.template.id!==template.id||captured.template.version!==template.version)throw new ApiError(409,'INSPECTION_SOURCE_CHANGED','模板候选已更新，请刷新候选并重新选择，不会自动升级版本','—');return captured});if(!selected||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();creationSource.value=selected;mode.value='CREATE';form.rows=worksheetEditorRows(selected.template.items);initial.value=JSON.stringify(payload());return true}
async function prepareFrom(row:WorksheetDetail){if(!canPrepare())return false;const turn=contextKey.value,target=structuredClone(row);if(!await discard()||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();baseline.value=target;mode.value=target.archived?'RESTORE':'UPDATE';form.rows=worksheetEditorRows(target.template_items,target.observations);form.timeKnown=target.reported_performed_at!==null;form.timeText=target.reported_performed_at??'';initial.value=JSON.stringify(payload());return true}
function setNoteKnown(index:number,known:boolean){if(locked.value||!form.rows[index]||form.rows[index]!.result==='')return;form.rows[index]!.note=known?form.rows[index]!.note??'':null}
function setNote(index:number,value:string){if(locked.value||!form.rows[index]||form.rows[index]!.result===''||form.rows[index]!.note===null)return;form.rows[index]!.note=value}
async function browse(next=false){inspectionSourceTarget.value=null;expandedVersion.value=null;return workspace.list(assetFilter.value,view.value,next)}
async function select(id:string){inspectionSourceTarget.value=null;expandedVersion.value=null;return workspace.select(id)}
async function history(id:string,next=false){inspectionSourceTarget.value=null;expandedVersion.value=null;return workspace.history(id,next)}
async function save(){if(locked.value||!mode.value)return false;validation.value='';const turn=contextKey.value,success=await workspace.submit(mode.value,payload(),baseline.value,creationSource.value);if(turn!==contextKey.value)return false;if(success)ElMessage.success('原请求收据已确认，仍为未核验人工草稿');else if(!state.value.attempt)validation.value='请核对人工结果、备注和带Z的UTC毫秒时间；未知时间保持未填写。未发送新请求';return success}
async function retry(){const turn=contextKey.value,success=await workspace.retry();if(success&&turn===contextKey.value)ElMessage.success('已恢复原请求收据，没有重复建单或重复修订');return success}
async function archiveWorksheet(row:WorksheetDetail){if(!canPrepare()||row.archived)return false;const turn=contextKey.value,target=structuredClone(row);if(!await discard()||turn!==contextKey.value)return false;try{await ElMessageBox.confirm('归档“'+target.asset_name+'”的人工执行单并保留全部修订，之后可明确恢复。是否继续？','确认归档人工草稿',{confirmButtonText:'归档并保留历史',cancelButtonText:'取消',type:'warning'})}catch{return false}if(turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();const success=await workspace.submit('ARCHIVE',{expected_version:target.version},target);if(success&&turn===contextKey.value)ElMessage.success('已归档，历史保留');return success}
function unlockRejected(){if(state.value.attempt?.state!=='rejected'||!workspace.begin())return false;validation.value='已保留输入并解锁。原基线不自动升级；请回读后明确按当前版本重新准备';return true}
async function closeEditor(){if(workspace.unresolved()){ElMessage.warning('原请求结果未知，不能关闭并丢失原请求');return false}const turn=contextKey.value;if(!await discard()||turn!==contextKey.value||state.value.busy)return false;if(state.value.attempt?.state==='rejected'&&!workspace.begin())return false;clearEditor();return true}
async function mayLeave(){if(workspace.unresolved()){ElMessage.warning('先恢复原请求结果，普通刷新不是原收据确认');return false}const turn=contextKey.value;return await discard()&&turn===contextKey.value}
onBeforeRouteLeave(mayLeave);const unregister=contextTransitionGuards.register(mayLeave)
function beforeUnload(event:BeforeUnloadEvent){if(workspace.unresolved()||unsaved.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onUnmounted(()=>{unregister();workspace.dispose();clearSources();clearEditor();window.removeEventListener('beforeunload',beforeUnload)})
defineExpose({loadAssets,loadTemplates,prepareCreate,prepareFrom,browse,select,history,save,retry,archiveWorksheet,unlockRejected,closeEditor,setNoteKnown,setNote,payload,form,state,assets,templates,selectedAssetId,selectedTemplateId,assetQuery,templateQuery,sourceError,hasUnresolved:workspace.unresolved})
</script>
<template>
 <section class="worksheet-page">
  <div class="page-heading"><div><span class="eyebrow">INSPECTION / MANUAL DRAFTS</span><h1>人工巡检执行单</h1><p>当前租户：{{ session?.tenant.name }} · 按冻结模板填写 · 修订历史保留</p></div></div>
  <el-alert type="warning" :closable="false" title="人工自述未核验，不能当作设备健康结论">本页不执行扫描，不自动填写正常，不绑定证据文件，不发布季度报告。模板批准与资产类型适用性仍未核验。</el-alert>
  <p v-if="!permitted" class="empty-panel">当前身份没有真实测试环境人工执行单读取权限</p>
  <template v-else>
   <section v-if="state.attempt" class="panel request-status" aria-live="polite"><h2>固定原请求：{{ actions[state.attempt.action] }}</h2><p v-if="state.attempt.state==='uncertain'">结果尚未确认。后续拒绝也不能证明之前没写入；普通刷新不能代替原收据确认。</p><p v-else-if="state.attempt.state==='accepted'">原请求收据已确认。它可能早于当前版本，请另行回读当前执行单。</p><p v-else>本次请求明确拒绝或派发前校验失败；输入和版本保持，不自动覆盖。</p><div class="actions"><button v-if="state.attempt.state==='uncertain'" type="button" :disabled="Boolean(state.busy)" @click="retry">使用完全相同原请求重试</button><button v-if="state.attempt.state==='rejected'" type="button" :disabled="Boolean(state.busy)" @click="unlockRejected">保留输入并解锁</button><button v-if="state.receipt" type="button" :disabled="Boolean(state.busy)" @click="select(state.receipt.id)">回读当前执行单</button></div></section>
   <ApiErrorNotice :error="state.error" /><ApiErrorNotice :error="sourceError" /><p v-if="state.busy||sourcesBusy" class="hint" role="status">{{ state.busy==='write'?'正在核对并提交固定原请求…':'正在只读查询并核对范围与摘要…' }}</p>
   <section v-if="writable" class="panel source-picker"><h2>新建来源选择</h2><p>明确选择资产和未归档模板，不会自动选择第一项。准备后绑定冻结，后续模板修改不会改变这张执行单。</p><p v-if="!canChooseSource" class="warning">当前缺少资产或模板读取能力，不能准备新单；不从历史缓存补齐来源。</p><fieldset :disabled="sourcesLocked"><div class="two-columns"><div><form v-form-feedback @submit.prevent="loadAssets(false)"><label>资产名称搜索<input v-model="assetQuery" aria-label="执行单资产搜索" /></label><div class="actions"><button type="submit">查询资产</button><button type="button" :disabled="!assets?.has_more||assetQuery!==assetApplied" @click="loadAssets(true)">更多资产</button></div></form><label>选择已登记资产<select v-model="selectedAssetId" aria-label="执行单绑定资产"><option value="">请明确选择</option><option v-for="asset in assets?.items??[]" :key="asset.id" :value="asset.id">{{ asset.name }} · {{ asset.id }}</option></select></label><p v-if="assets===null" class="hint">尚无已核对的资产列表，数量未知</p><p v-else-if="!assets.items.length" class="hint">当前搜索没有可见资产</p></div><div><form v-form-feedback @submit.prevent="loadTemplates(false)"><label>模板名称搜索<input v-model="templateQuery" aria-label="执行单模板搜索" /></label><div class="actions"><button type="submit">查询未归档模板</button><button type="button" :disabled="!templates?.has_more||templateQuery!==templateApplied" @click="loadTemplates(true)">更多模板</button></div></form><label>选择未发布模板候选<select v-model="selectedTemplateId" aria-label="执行单冻结模板"><option value="">请明确选择</option><option v-for="row in templates?.items??[]" :key="row.id" :value="row.id">{{ row.name }} · {{ row.device_type }} · v{{ row.version }}</option></select></label><p v-if="templates===null" class="hint">尚无已核对的模板列表，数量未知</p><p v-else-if="!templates.items.length" class="hint">当前搜索没有未归档候选，请先维护模板</p></div></div><button class="primary-button" type="button" :disabled="!selectedAssetId||!selectedTemplateId" @click="prepareCreate">按所选来源准备新单</button></fieldset></section>
   <form v-form-feedback v-if="mode" class="panel worksheet-editor" @submit.prevent="save"><h2>{{ actions[mode] }}人工执行单 <small>{{ baseline?`基线 v${baseline.version}`:'新草稿' }}</small></h2><p>{{ baseline?.asset_name??creationSource?.asset.name }} · {{ baseline?.template_name??creationSource?.template.name }} · 冻结模板 v{{ baseline?.template_version??creationSource?.template.version }}</p><p class="hint">资产名称由服务端在保存时读取；这里不是完整资产版本快照。模板适用性未核验。</p><p v-if="newerVersion" class="warning">当前回读版本已变化，表单仍保留原基线；请明确重新准备，不会自动覆盖。</p><fieldset :disabled="locked"><label class="checkbox-label"><input v-model="form.timeKnown" type="checkbox" aria-label="明确填写自述巡检时间" />明确填写自述巡检时间；不勾选保持未知（null）</label><label>自述已巡检时间（UTC，必须带 Z）<input v-model="form.timeText" aria-label="自述巡检UTC时间" :disabled="!form.timeKnown" :required="form.timeKnown" placeholder="例如 2026-10-04T01:30:00Z，不自动填当前时间" /></label><p class="hint">未知巡检时间不能用系统记录时间替代；非空仍是人工自述，不代表已核验。</p>
    <ol class="worksheet-editor-items"><li v-for="(entry,index) in form.rows" :key="entry.item.key"><h3>{{ index+1 }}. {{ entry.item.label }}</h3><p class="hint">{{ entry.item.section }} · {{ entry.item.key }}</p><p class="instruction">{{ entry.item.instruction===null?'检查说明未填写':entry.item.instruction===''?'明确空说明':entry.item.instruction }}</p><label>人工结果<select v-model="entry.result" :aria-label="`检查项${index+1}人工结果`"><option value="">未填写（不算正常）</option><option value="NORMAL">正常（人工填写）</option><option value="ATTENTION">建议关注（人工填写）</option><option value="REQUIRES_ACTION">需处理（人工填写）</option></select></label><label class="checkbox-label"><input type="checkbox" :checked="entry.note===null" :disabled="entry.result===''" :aria-label="`检查项${index+1}备注未填写`" @change="setNoteKnown(index,!($event.target as HTMLInputElement).checked)" />备注未填写（null）</label><label>人工备注<textarea :value="entry.note??''" :disabled="entry.result===''||entry.note===null" :aria-label="`检查项${index+1}人工备注`" @input="setNote(index,($event.target as HTMLTextAreaElement).value)" /></label><p v-if="entry.result===''" class="hint">本项不会提交结果或备注；改回一个明确结果可继续编辑，原修订历史仍保留。</p></li></ol><p class="hint">证据文件绑定尚未实现，本页不会宣称文件已上传或授予访问。</p><button class="primary-button" type="submit">{{ mode==='CREATE'?'保存人工草稿':mode==='RESTORE'?'明确恢复并保存修订':'保存新修订' }}</button></fieldset><p v-if="validation" class="warning" role="alert">{{ validation }}</p><button type="button" :disabled="Boolean(state.busy)" @click="closeEditor">关闭输入</button></form>
   <p v-if="validation&&!mode" class="warning" role="alert">{{ validation }}</p>
   <section v-if="state.receipt" class="panel receipt-panel"><h2>原请求确认收据 · v{{ state.receipt.version }}</h2><p>{{ state.receipt.asset_name }} · {{ actions[state.receipt.action] }} · {{ state.receipt.archived?'已归档':'未核验人工草稿' }}</p><details><summary>展开原收据（不是当前状态）</summary><InspectionWorksheetFacts :value="state.receipt" /></details></section>
   <section class="panel"><form v-form-feedback class="filters" @submit.prevent="browse(false)"><label>资产ID筛选（留空为全部）<input v-model="assetFilter" aria-label="执行单列表资产筛选" /></label><label>记录范围<select v-model="view" aria-label="执行单归档视图"><option value="CURRENT">未归档</option><option value="ARCHIVED">已归档</option><option value="ALL">全部历史保留记录</option></select></label><button type="submit" :disabled="Boolean(state.busy)">查询 / 刷新第一页</button></form><p v-if="state.page===null" class="empty-panel">{{ state.busy==='read'?'正在读取，数量未知':state.error?'读取未通过，未显示旧列表；请重试':'尚未读取，数量未知' }}</p><template v-else><div class="worksheet-table-wrap" role="region" tabindex="0" aria-label="人工巡检执行单列表，可横向滚动"><table><thead><tr><th scope="col">资产 / 冻结模板</th><th scope="col">草稿状态</th><th scope="col">实际填写</th><th scope="col">自述巡检时间</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="row in state.page.items" :key="row.id"><td><strong>{{ row.asset_name }}</strong><small>{{ row.template_name }} · 模板 v{{ row.template_version }}</small></td><td>{{ row.archived?'已归档':'未核验人工草稿' }} · v{{ row.version }}</td><td>已填 {{ row.summary.answered }}/{{ row.summary.total }}<small>未填 {{ row.summary.unanswered }}，不算正常</small></td><td>{{ row.reported_performed_at===null?'未填写（null）':displayTime(row.reported_performed_at) }}</td><td><button type="button" :disabled="Boolean(state.busy)" @click="select(row.id)">查看执行单</button></td></tr></tbody></table></div><p v-if="!state.page.items.length" class="empty-panel">当前筛选无已记录的执行单；不代表已巡检或设备正常</p><div class="actions table-footer"><span>本页 {{ state.page.items.length }} 条 · {{ state.paged?'续页':'第一页' }}</span><button v-if="state.paged" type="button" :disabled="Boolean(state.busy)" @click="browse(false)">返回第一页</button><button type="button" :disabled="!nextList" @click="browse(true)">下一页</button></div></template></section>
   <section v-if="state.selected" class="panel current-worksheet"><h2>当前回读：{{ state.selected.asset_name }}</h2><p>{{ state.selected.archived?'已归档':'未核验人工草稿' }} · v{{ state.selected.version }}</p><div class="actions"><button v-if="writable" type="button" :disabled="Boolean(state.busy)||sourcesBusy||workspace.unresolved()" @click="prepareFrom(state.selected)">{{ state.selected.archived?'按当前版本准备恢复':'按当前版本编辑' }}</button><button v-if="writable&&!state.selected.archived" type="button" :disabled="Boolean(state.busy)||sourcesBusy||workspace.unresolved()" @click="archiveWorksheet(state.selected)">归档并保留历史</button><button type="button" :disabled="Boolean(state.busy)" @click="history(state.selected.id)">读取修订历史</button></div><button type="button" @click="inspectionSourceTarget={worksheetId:state.selected.id,version:state.selected.version,contentSha256:state.selected.content_sha256}">核对当前回读版本来源</button><InspectionWorksheetFacts :value="state.selected" /></section>
   <section v-if="state.history" class="panel worksheet-history"><h2>冻结修订历史</h2><article v-for="entry in state.history.items" :key="entry.version"><div class="item-heading"><h3>v{{ entry.version }} · {{ actions[entry.action] }}</h3><button type="button" :aria-expanded="expandedVersion===entry.version" @click="expandedVersion=expandedVersion===entry.version?null:entry.version">{{ expandedVersion===entry.version?'收起该版内容':'查看该版内容' }}</button></div><p>{{ displayTime(entry.recorded_at) }} · 已填 {{ entry.summary.answered }}/{{ entry.summary.total }} · 人工自述未核验</p><button type="button" @click="inspectionSourceTarget={worksheetId:state.history.worksheet_id,version:entry.version,contentSha256:entry.content_sha256}">核对 v{{ entry.version }} 来源</button><InspectionWorksheetFacts v-if="expandedVersion===entry.version" :value="entry" /></article><div class="actions"><button type="button" :disabled="Boolean(state.busy)" @click="history(state.history.worksheet_id)">读取最新历史</button><button type="button" :disabled="Boolean(state.busy)||!state.history.has_more" @click="history(state.history.worksheet_id,true)">更早的历史</button></div></section>
   <InspectionSourceRevisionReader v-if="inspectionSourceTarget" :context="context()" :target="inspectionSourceTarget" @close="inspectionSourceTarget=null" />
  </template>
 </section>
</template>
